{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C35"],
      "claim": "Indomethacin has an absolute oral bioavailability of 98% in adult humans, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C34"],
      "claim": "Rigosertib has an absolute oral bioavailability of 35% after a single fasting 560 mg oral dose in patients, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Omeprazole has an absolute oral bioavailability of about 30-40% in humans, above the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All transferred evidence molecules with ordinary adult condition measurements show absolute oral bioavailability values above 20%, strongly supporting a high F>=20 prediction. Lower values are limited to special populations or altered conditions.",
  "evidence_gaps": [
    "Some records report lower bioavailability in preterm infants for indomethacin (13-20%) and in fed-state rigosertib (13.9%), but these are population- or condition-specific.",
    "One evidence record for GDC-0810 is PBPK-predicted rather than clinically measured.",
    "Loratadine evidence is qualitative ('good bioavailability') without a numeric absolute bioavailability value."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

